Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
openvswitch: validate MPLS set/set_masked payload length

validate_set() accepted OVS_KEY_ATTR_MPLS as variable-sized payload for
SET/SET_MASKED actions. In action handling, OVS expects fixed-size
MPLS key data (struct ovs_key_mpls).

Use the already normalized key_len (masked case included) and reject
non-matching MPLS action key sizes.

Reject invalid MPLS action payload lengths early.

Fixes: fbdcdd78da7c ("Change in Openvswitch to support MPLS label depth of 3 in ingress direction")
Reported-by: Yifan Wu <yifanwucs@gmail.com>
Reported-by: Juefei Pu <tomapufckgml@gmail.com>
Tested-by: Ao Zhou <n05ec@lzu.edu.cn>
Co-developed-by: Yuan Tan <tanyuan98@outlook.com>
Signed-off-by: Yuan Tan <tanyuan98@outlook.com>
Suggested-by: Xin Liu <bird@lzu.edu.cn>
Signed-off-by: Yang Yang <n05ec@lzu.edu.cn>
Reviewed-by: Ilya Maximets <i.maximets@ovn.org>
Link: https://patch.msgid.link/20260319080228.3423307-1-n05ec@lzu.edu.cn
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The validate_set() function in flow_netlink.c accepted OVS_KEY_ATTR_MPLS payloads of any length for SET/SET_MASKED actions, but the subsequent action handling code expected a fixed-size struct ovs_key_mpls. This mismatch could cause out-of-bounds reads or memory corruption when processing malformed netlink messages.

Here is the patch:

 static int validate_set(const struct nlattr *a,
 			const struct sw_flow_key *flow_key,
 			struct sw_flow_actions **sfa, bool *skip_copy,
 			u8 mac_proto, __be16 eth_type, bool masked, bool log)
 {
 	const struct nlattr *ovs_key = nla_data(a);
 	int key_type = nla_type(ovs_key);
 	size_t key_len;

 	/* There can be only one key in a action */
 	if (!nla_ok(ovs_key, nla_len(a)) ||
 	    nla_total_size(nla_len(ovs_key)) != nla_len(a))
 		return -EINVAL;

 	key_len = nla_len(ovs_key);
 	if (masked)
 		key_len /= 2;

 	if (key_type > OVS_KEY_ATTR_MAX ||
 	    !check_attr_len(key_len, ovs_key_lens[key_type].len))
 		return -EINVAL;

 	if (masked && !validate_masked(nla_data(ovs_key), key_len))
 		return -EINVAL;

 	switch (key_type) {
 	case OVS_KEY_ATTR_PRIORITY:
 	case OVS_KEY_ATTR_SKB_MARK:
 	case OVS_KEY_ATTR_CT_MARK:
 	case OVS_KEY_ATTR_CT_LABELS:
 		break;

 	case OVS_KEY_ATTR_ETHERNET:
 		if (mac_proto != MAC_PROTO_ETHERNET)
 			return -EINVAL;
 		break;

 	case OVS_KEY_ATTR_TUNNEL: {
 		int err;

 		if (masked)
 			return -EINVAL; /* Masked tunnel set not supported. */

 		*skip_copy = true;
 		err = validate_and_copy_set_tun(a, sfa, log);
 		if (err)
 			return err;
 		break;
 	}
 	case OVS_KEY_ATTR_IPV4: {
 		const struct ovs_key_ipv4 *ipv4_key;

 		if (eth_type != htons(ETH_P_IP))
 			return -EINVAL;

 		ipv4_key = nla_data(ovs_key);

 		if (masked) {
 			const struct ovs_key_ipv4 *mask = ipv4_key + 1;

 			/* Non-writeable fields. */
 			if (mask->ipv4_proto || mask->ipv4_frag)
 				return -EINVAL;
 		} else {
 			if (ipv4_key->ipv4_proto != flow_key->ip.proto)
 				return -EINVAL;

 			if (ipv4_key->ipv4_frag != flow_key->ip.frag)
 				return -EINVAL;
 		}
 		break;
 	}
 	case OVS_KEY_ATTR_IPV6: {
 		const struct ovs_key_ipv6 *ipv6_key;

 		if (eth_type != htons(ETH_P_IPV6))
 			return -EINVAL;

 		ipv6_key = nla_data(ovs_key);

 		if (masked) {
 			const struct ovs_key_ipv6 *mask = ipv6_key + 1;

 			/* Non-writeable fields. */
 			if (mask->ipv6_proto || mask->ipv6_frag)
 				return -EINVAL;

 			/* Invalid bits in the flow label mask? */
 			if (ntohl(mask->ipv6_label) & 0xFFF00000)
 				return -EINVAL;
 		} else {
 			if (ipv6_key->ipv6_proto != flow_key->ip.proto)
 				return -EINVAL;

 			if (ipv6_key->ipv6_frag != flow_key->ip.frag)
 				return -EINVAL;
 		}
 		if (ntohl(ipv6_key->ipv6_label) & 0xFFF00000)
 			return -EINVAL;

 		break;
 	}
 	case OVS_KEY_ATTR_TCP:
 		if ((eth_type != htons(ETH_P_IP) &&
 		     eth_type != htons(ETH_P_IPV6)) ||
 		    flow_key->ip.proto != IPPROTO_TCP)
 			return -EINVAL;

 		break;

 	case OVS_KEY_ATTR_UDP:
 		if ((eth_type != htons(ETH_P_IP) &&
 		     eth_type != htons(ETH_P_IPV6)) ||
 		    flow_key->ip.proto != IPPROTO_UDP)
 			return -EINVAL;

 		break;

 	case OVS_KEY_ATTR_MPLS:
 		if (!eth_p_mpls(eth_type))
 			return -EINVAL;
+		if (key_len != sizeof(struct ovs_key_mpls))
+			return -EINVAL;
 		break;

 	case OVS_KEY_ATTR_SCTP:
 		if ((eth_type != htons(ETH_P_IP) &&
 		     eth_type != htons(ETH_P_IPV6)) ||
 		    flow_key->ip.proto != IPPROTO_SCTP)
 			return -EINVAL;

 		break;

 	default:
 		return -EINVAL;
 	}

 	/* Convert non-masked non-tunnel set actions to masked set actions. */
 	if (!masked && key_type != OVS_KEY_ATTR_TUNNEL) {
 		int start, len = key_len * 2;
 		struct nlattr *at;

 		*skip_copy = true;

 		start = add_nested_action_start(sfa,
 						OVS_ACTION_ATTR_SET_TO_MASKED,
 						log);
 		if (start < 0)
 			return start;

 		at = __add_action(sfa, key_type, NULL, len, log);
 		if (IS_ERR(at))
 			return PTR_ERR(at);

 		memcpy(nla_data(at), nla_data(ovs_key), key_len); /* Key. */
 		memset(nla_data(at) + key_len, 0xff, key_len);    /* Mask. */
 		/* Clear non-writeable bits from otherwise writeable fields. */
 		if (key_type == OVS_KEY_ATTR_IPV6) {
 			struct ovs_key_ipv6 *mask = nla_data(at) + key_len;

 			mask->ipv6_label &= htonl(0x000FFFFF);
 		}
 		add_nested_action_end(*sfa, start);
 	}

 	return 0;
 }



